// watch node puts the full path in msg.payload.
// file in node wants msg.filename.
const imagePath = msg.payload
const jsonPath = imagePath.replace(/\.[^.]+$/, '') + '.json'

msg.filename = imagePath
msg.imagePath = imagePath
msg.jsonPath = jsonPath

// Remember the bare filename for logging.
msg.imageName = imagePath.split(/[\\/]/).pop()

// Clear msg.payload — we don't want to accidentally stream it to the file in node.
msg.payload = null
return msg

// Pretty-print the JSON for the .json file next to the image.
msg.payload = JSON.stringify(msg.payload, null, 2)
return msg
